export class HTTPResponse{constructor(){}ok(){const t=this.status();return 0===t||t>=200&&t<=299}async buffer(){const t=await this.content();return Buffer.from(t)}async text(){const t=await this.content();return new TextDecoder("utf-8",{fatal:!0}).decode(t)}async json(){const t=await this.text();return JSON.parse(t)}}